nodes.command:
node -e "
const fs = require('fs');
const path = '${inputs.project_root}/src/data/character-registry.json';
let registry = fs.existsSync(path) ? JSON.parse(fs.readFileSync(path)) : { characters: {} };
registry.characters['${inputs.character_id}'] = {
  name: '${inputs.character_name}',
  type: '${inputs.character_type}',
  color: '${inputs.color}',
  icon: '${inputs.icon}',
  asset_mode: 'whitebox',
  updated_at: new Date().toISOString()
};
fs.writeFileSync(path, JSON.stringify(registry, null, 2));
console.log('Registry updated for:', '${inputs.character_id}');
"
